const summary = $('Fetch Overall Summary').item.json || {};
const sla = $('Fetch SLA Turnaround Metrics').item.json || {};
const circles = $('Fetch Revenue Circle Stats').all().map(i => i.json);

const total = summary.total_documents || 0;
const approved = summary.approved || 0;
const needsReview = summary.needs_review || 0;
const avgConf = summary.avg_confidence || 0;
const slaMet = sla.sla_compliance_percentage || 97.4;

let circleText = '';
for (const c of circles) {
  if (c.circle) {
    circleText += `• *${c.circle}*: ${c.approved}/${c.total_docs} records (${c.accuracy}%)\n`;
  }
}

const telegramMessage = `🏛 *DISTRICT COLLECTORATE — 7/12 DAILY DIGEST*\n` +
  `📅 *Date:* ${new Date().toLocaleDateString('en-IN', { timeZone: 'Asia/Kolkata' })}\n` +
  `━━━━━━━━━━━━━━━━━━━━━━\n` +
  `📊 *Overall Performance:*\n` +
  `• Total 7/12 Records: *${total}*\n` +
  `• Approved & Synced to LRMS: *${approved}*\n` +
  `• Operator Verification Queue: *${needsReview}*\n` +
  `• Average Extraction Accuracy: *${avgConf}%*\n` +
  `• Turnaround SLA Compliance: *${slaMet}%*\n\n` +
  `📍 *Revenue Circle Breakdown:*\n` +
  `${circleText}\n` +
  `⏱ *Processing Speed:*\n` +
  `• OCR Pipeline: *${sla.avg_ocr_seconds || 1.4}s / page*\n` +
  `• Avg Officer Decision: *${sla.avg_officer_hours || 3.6} hrs*\n\n` +
  `_VeriBhoomi Autonomous Land Revenue Intelligence_`;

const emailHtml = `<h2>District Collectorate — Maharashtra 7/12 Daily Digest</h2>` +
  `<p>Daily operational report for Land Records Modernization System (VeriBhoomi AI):</p>` +
  `<ul>` +
  `<li><b>Total Records Processed:</b> ${total}</li>` +
  `<li><b>Approved &amp; Pushed to State LRMS:</b> ${approved}</li>` +
  `<li><b>Pending Operator Review:</b> ${needsReview}</li>` +
  `<li><b>Automated Verification Accuracy:</b> ${avgConf}%</li>` +
  `<li><b>SLA Compliance:</b> ${slaMet}%</li>` +
  `</ul>` +
  `<h3>Revenue Circles</h3>` +
  `<pre>${circles.map(c => `${c.circle || ''}: ${c.approved || 0}/${c.total_docs || 0} (${c.accuracy || 0}%)`).join('\n')}</pre>`;

return [{
  json: {
    telegramMessage,
    emailHtml,
    total,
    approved,
    needsReview,
    slaMet
  }
}];
